#include <stdio.h>

typedef struct { int x; int paused; } Game;

void update(Game *g) {
    g->x += 10;
}

void render(const Game *g) {
    printf("x = %d\n", g->x);
}

int main() {
    Game g = {0, 0};
    for (int frame = 1; frame <= 5; frame++) {
        g.paused = (frame == 3 || frame == 4);
        if (!g.paused) update(&g);
        render(&g);
    }
    return 0;
}

#include <stdio.h>

float run(int fps, float speed) {
    float x = 0.0f;
    float dt = 1.0f / fps;
    for (int frame = 0; frame < fps; frame++) {
        x += speed * dt;
    }
    return x;
}

int main() {
    printf("30 fps: %.1f\n", run(30, 120.0f));
    printf("60 fps: %.1f\n", run(60, 120.0f));
    return 0;
}

#include <stdio.h>

typedef enum { MENU, PLAYING, GAME_OVER } State;
const char *names[] = { "MENU", "PLAYING", "GAME_OVER" };

int main() {
    State state = MENU;
    for (int frame = 1; frame <= 5; frame++) {
        State next_state = state;
        switch (state) {
        case MENU:
            if (frame == 2) next_state = PLAYING;
            break;
        case PLAYING:
            if (frame == 4) next_state = GAME_OVER;
            break;
        case GAME_OVER:
            break;
        }
        printf("frame %d: %s\n", frame, names[state]);
        state = next_state;
    }
    return 0;
}

#include <stdio.h>

typedef struct { int x, y, w, h; } Box;

int overlap(Box a, Box b) {
    return a.x < b.x + b.w && a.x + a.w > b.x &&
           a.y < b.y + b.h && a.y + a.h > b.y;
}

int main() {
    Box player = {10, 10, 20, 20};
    Box corner = {25, 25, 20, 20};
    Box touching = {30, 10, 20, 20};
    Box far_away = {50, 50, 10, 10};
    Box inside = {15, 15, 5, 5};
    printf("%d\n", overlap(player, corner));
    printf("%d\n", overlap(player, touching));
    printf("%d\n", overlap(player, far_away));
    printf("%d\n", overlap(player, inside));
    return 0;
}

#include <windows.h>
#include <stdio.h>
#include <string.h>

int score = 12;

LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
    if (msg == WM_PAINT) {
        PAINTSTRUCT ps;
        HDC hdc = BeginPaint(hwnd, &ps);
        char buf[32];
        snprintf(buf, sizeof buf, "Score: %d", score);
        TextOut(hdc, 10, 10, buf, (int)strlen(buf));
        EndPaint(hwnd, &ps);
        return 0;
    }
    if (msg == WM_DESTROY) { PostQuitMessage(0); return 0; }
    return DefWindowProc(hwnd, msg, wp, lp);
}

int WINAPI WinMain(HINSTANCE hi, HINSTANCE hp, LPSTR cmd, int show) {
    WNDCLASS wc = {0};
    MSG m;
    (void)hp; (void)cmd; (void)show;
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hi;
    wc.lpszClassName = "ScoreWin";
    wc.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
    RegisterClass(&wc);
    CreateWindow("ScoreWin", "Score", WS_OVERLAPPEDWINDOW | WS_VISIBLE, 100, 100, 320, 200, NULL, NULL, hi, NULL);
    while (GetMessage(&m, NULL, 0, 0)) DispatchMessage(&m);
    return 0;
}
